using Microsoft.AspNetCore.Mvc;

[ApiController]
[Route("api/[controller]")]
public class ProductsController : ControllerBase
{
    private static readonly List<Product> _items = new() { new(1, "Pen", 2.5m) };

    [HttpGet]
    public ActionResult<IEnumerable<Product>> GetAll() => Ok(_items);

    [HttpGet("{id:int}")]
    public ActionResult<Product> GetOne(int id)
    {
        var p = _items.FirstOrDefault(x => x.Id == id);
        return p is null ? NotFound() : Ok(p);
    }
}
public record Product(int Id, string Name, decimal Price);

using System.ComponentModel.DataAnnotations;

public class CreateProductDto
{
    [Required, StringLength(50)] public string Name { get; set; } = "";
    [Range(0.01, 100000)] public decimal Price { get; set; }
}

[HttpPost]
public ActionResult<Product> Create(CreateProductDto dto)
{
    var p = new Product(_items.Count + 1, dto.Name, dto.Price);
    _items.Add(p);
    return CreatedAtAction(nameof(GetOne), new { id = p.Id }, p);
}

[HttpDelete("{id:int}")]
public IActionResult Delete(int id)
{
    var p = _items.FirstOrDefault(x => x.Id == id);
    if (p is null) return NotFound();
    _items.Remove(p);
    return NoContent();
}

