interface IDiscount { decimal Apply(decimal p); }
class NoDiscount : IDiscount { public decimal Apply(decimal p) => p; }
class Percent : IDiscount { readonly decimal _r; public Percent(decimal r) => _r = r; public decimal Apply(decimal p) => p * (1 - _r); }
class Cart { public IDiscount Strategy = new NoDiscount(); public decimal Total(decimal p) => Strategy.Apply(p); }
